{"code": "import os
# Check if the directory exists and what files are in it
if os.path.exists('data/train/train'):
    files = os.listdir('data/train/train')
    print(f"Number of files in data/train/train: {len(files)}")
    print(f"First 10 files: {files[:10]}")
    # Check file sizes
    print(f"\nFile sizes for first 5 files:")
    for f in files[:5]:
        filepath = os.path.join('data/train/train', f)
        print(f"{f}: {os.path.getsize(filepath)} bytes")
        # Check first few bytes
        with open(filepath, 'rb') as fp:
            first_bytes = fp.read(50)
            if b'version https://git-lfs.github.com' in first_bytes:
                print(f"  -> Git LFS pointer file")
            elif first_bytes.startswith(b'\xff\xd8'):
                print(f"  -> JPEG image")
            else:
                print(f"  -> Unknown format")
else:
    print("Directory 'data/train/train' does not exist")"}

